import React from 'react';
import { Activity, AlertCircle, Star, CheckCircle } from 'lucide-react';
import { Card, CardContent } from '../ui/Card';
import { QCStats } from '../../types';
import { cn } from '../../lib/utils';

interface QCStatsCardsProps {
  stats: QCStats;
}

interface StatCard {
  label: string;
  value: string | number;
  icon: typeof Activity;
  color: string;
  suffix: string;
  score?: number;
  isText?: boolean;
}

const QCStatsCards: React.FC<QCStatsCardsProps> = ({ stats }) => {
  const getScoreColor = (score: number) => {
    if (score >= 4.5) return 'text-vibrant-green';
    if (score >= 3.5) return 'text-vibrant-blue';
    if (score >= 2.5) return 'text-vibrant-amber';
    return 'text-vibrant-red';
  };

  const statCards: StatCard[] = [
    {
      label: 'Batch Approval Rate',
      value: stats.passRate ?? 0,
      icon: CheckCircle,
      color: 'green',
      suffix: '%',
    },
    {
      label: 'Total Inspections',
      value: stats.totalInspections ?? 0,
      icon: Activity,
      color: 'chocolate',
      suffix: '',
    },
    {
      label: 'Avg Quality Score',
      value: stats.averageScore ?? 0,
      icon: Star,
      color: 'score',
      suffix: '/5',
      score: stats.averageScore ?? 0,
    },
    {
      label: 'Most Common Defect',
      value: 'Minor Surface',
      icon: AlertCircle,
      color: 'red',
      suffix: '',
      isText: true,
    },
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
      {statCards.map((stat, index) => {
        const Icon = stat.icon;
        const isScore = stat.color === 'score';

        return (
          <Card
            key={index}
            className={cn(
               "hover:shadow-2xl hover:shadow-chocolate-900/10 hover:-translate-y-2 transition-all duration-500 rounded-[2.5rem] border border-chocolate-100 group relative overflow-hidden bg-white",
               isScore && `border-b-4 ${getScoreColor(stat.score || 0).replace('text-', 'border-b-')}`,
               stat.color === 'red' && 'border-b-4 border-b-vibrant-red'
            )}
          >
           <CardContent className="p-8 relative z-10">
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <p
                  className={cn(
                    "text-[10px] font-black uppercase tracking-[0.2em] mb-3 transition-colors duration-500",
                    isScore
                      ? getScoreColor(stat.score ?? 0)
                      : stat.color === 'red'
                      ? 'text-vibrant-red'
                      : 'text-chocolate-400 group-hover:text-chocolate-600'
                  )}
                >
                  {stat.label}
                </p>
                <div className="flex items-baseline gap-2">
                  <h4
                    className={cn(
                      "text-4xl font-black tracking-tight",
                      stat.isText
                        ? 'text-chocolate-900'
                        : isScore
                        ? getScoreColor(stat.score ?? 0)
                        : stat.color === 'red'
                        ? 'text-vibrant-red'
                        : 'text-chocolate-950'
                    )}
                  >
                    {typeof stat.value === 'number' && !stat.isText ? stat.value.toFixed(stat.suffix ? 1 : 0) : stat.value}
                  </h4>
                  {!stat.isText && (
                    <span className="text-sm font-black text-chocolate-300 uppercase tracking-widest">{stat.suffix}</span>
                  )}
                </div>
              </div>

              <div
                className={cn(
                  "p-4 rounded-[1.25rem] transition-all duration-700 group-hover:scale-110 group-hover:rotate-6 shadow-inner ring-1 ring-black/5",
                  isScore
                    ? getScoreColor(stat.score ?? 0).replace('text-', 'bg-').concat('/10 ').concat(getScoreColor(stat.score ?? 0))
                    : stat.color === 'red'
                    ? 'bg-vibrant-red/10 text-vibrant-red'
                    : 'bg-chocolate-50 text-chocolate-400 group-hover:text-chocolate-600'
                )}
              >
                <Icon className="w-6 h-6" />
              </div>
            </div>
           </CardContent>
           <div className={cn(
              "absolute -right-4 -bottom-4 w-24 h-24 blur-3xl opacity-0 group-hover:opacity-10 transition-opacity duration-700 rounded-full",
              isScore ? getScoreColor(stat.score ?? 0).replace('text-', 'bg-') : 
              stat.color === 'red' ? 'bg-vibrant-red' : 'bg-chocolate-600'
           )} />
          </Card>
        );
      })}
    </div>
  );
};

export default QCStatsCards;
